// S2 赔率异动规则引擎(与 detect_anomaly.py 同逻辑,阈值可热改)
const TH = { steamDrop: 0.15, reverseGap: 0.10, conc: 0.80, bigHandle: 120000, lowCount: 200 };
const out = [];
for (const m of $input.first().json.matches) {
  const flags = [];
  const hd = (m.current.home - m.opening.home) / m.opening.home;
  const ad = (m.current.away - m.opening.away) / m.opening.away;
  const hp = m.handle_home_pct;
  if (hd <= -TH.steamDrop || ad <= -TH.steamDrop) flags.push({ rule: 'R1_赔率急跌', severity: 'high' });
  if (hp >= 0.65 && hd >= TH.reverseGap) flags.push({ rule: 'R2_反向线动', severity: 'high' });
  if (Math.max(hp, 1 - hp) >= TH.conc) flags.push({ rule: 'R3_投注集中', severity: 'mid' });
  if (m.handle_usdt >= TH.bigHandle) flags.push({ rule: 'R4_大额盘口', severity: 'mid' });
  if (m.handle_usdt >= TH.bigHandle * 0.5 && m.bet_count < TH.lowCount) flags.push({ rule: 'R5_少笔大额', severity: 'high' });
  if (flags.length) out.push({ match_id: m.match_id, sport: m.sport, match: m.home + ' vs ' + m.away, handle_usdt: m.handle_usdt, flags });
}
return [{ json: { date: $today.format('yyyy-MM-dd'), anomalies: out } }];

